import networkx as nx
G = nx.Graph()
for i in range(14):
    for j in range(i+1, 14):
        G.add_edge(i, j)
for u in range(14):
    for v in range(u+1, 14):
        for w in range(v+1, 14):
            if G.has_edge(u, v) and G.has_edge(v, w) and G.has_edge(w, u):
                G.remove_edge(v, w)
print(list(G.edges))
